private async Task<T> InvokeWithRetry<T>(Func<Task<T>> executeRequest, Func<T, int, RetryPolicyResult> getRetryPolicyResult, CancellationToken cancellationToken) where T : IRestResponse
{
    T response = default(T);
    Guid? clientRequestId = null;
    int previousAttemptCount = 0;

    do
    {
        if (response != null)
        {
            await this.delayable.Delay(this.retryDelay.GetRetryDelay(response));
        }

        response = await executeRequest();
        previousAttemptCount++;

        if (!clientRequestId.HasValue)
        {
            var requestHeaderHelper = new RequestHeaderHelper(response.Request);
            clientRequestId = requestHeaderHelper.GetHeaderValueAsGuid(Headers.ClientRequestId);
        }
    }
    while (this.ShouldRetry(response, getRetryPolicyResult, cancellationToken.IsCancellationRequested, clientRequestId.Value, previousAttemptCount));

    return response;
}
